CREATE DATABASE IF NOT EXISTS smart_parking_test_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_parking_test_db;
CREATE TABLE IF NOT EXISTS vehicles (registration_number VARCHAR(15) PRIMARY KEY, owner_name VARCHAR(120) NOT NULL, vehicle_type ENUM('CAR','BIKE','TRUCK') NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parking_slots (slot_id VARCHAR(20) PRIMARY KEY, floor_number INT NOT NULL, slot_size INT NOT NULL, distance_from_entrance INT NOT NULL, available BOOLEAN NOT NULL DEFAULT TRUE, CHECK(slot_size BETWEEN 1 AND 3));
CREATE TABLE IF NOT EXISTS waiting_queue (queue_id BIGINT PRIMARY KEY AUTO_INCREMENT, registration_number VARCHAR(15) NOT NULL UNIQUE, enqueued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_waiting_vehicle FOREIGN KEY(registration_number) REFERENCES vehicles(registration_number) ON DELETE CASCADE, INDEX idx_waiting_order(queue_id));
CREATE TABLE IF NOT EXISTS parking_tickets (ticket_id CHAR(36) PRIMARY KEY, registration_number VARCHAR(15) NOT NULL, slot_id VARCHAR(20) NOT NULL, entry_time DATETIME NOT NULL, exit_time DATETIME NULL, amount DECIMAL(10,2) NULL, status ENUM('ACTIVE','CLOSED') NOT NULL DEFAULT 'ACTIVE', active_registration VARCHAR(15) GENERATED ALWAYS AS (CASE WHEN status='ACTIVE' THEN registration_number ELSE NULL END) STORED, CONSTRAINT fk_ticket_vehicle FOREIGN KEY(registration_number) REFERENCES vehicles(registration_number), CONSTRAINT fk_ticket_slot FOREIGN KEY(slot_id) REFERENCES parking_slots(slot_id), UNIQUE KEY uq_ticket_one_active(active_registration), INDEX idx_ticket_vehicle_status(registration_number,status), INDEX idx_ticket_entry(entry_time));
CREATE TABLE IF NOT EXISTS payments (payment_id BIGINT PRIMARY KEY AUTO_INCREMENT, ticket_id CHAR(36) NOT NULL UNIQUE, method ENUM('CASH','UPI','CARD') NOT NULL, amount DECIMAL(10,2) NOT NULL, status ENUM('PAID','FAILED') NOT NULL, paid_at DATETIME NOT NULL, FOREIGN KEY(ticket_id) REFERENCES parking_tickets(ticket_id));
CREATE TABLE IF NOT EXISTS parking_history (history_id BIGINT PRIMARY KEY AUTO_INCREMENT, ticket_id CHAR(36) NOT NULL UNIQUE, registration_number VARCHAR(15) NOT NULL, slot_id VARCHAR(20) NOT NULL, entry_time DATETIME NOT NULL, exit_time DATETIME NOT NULL, duration_minutes BIGINT NOT NULL, fee DECIMAL(10,2) NOT NULL, FOREIGN KEY(ticket_id) REFERENCES parking_tickets(ticket_id), FOREIGN KEY(registration_number) REFERENCES vehicles(registration_number), FOREIGN KEY(slot_id) REFERENCES parking_slots(slot_id), INDEX idx_history_vehicle(registration_number));
